'use strict';
const $=s=>document.querySelector(s);
const $$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeUrl=v=>{try{const u=new URL(v);return u.protocol==='https:'||u.protocol==='http:'?u.href:'#'}catch{return '#'}};
const fmt=n=>Number(n).toLocaleString('en-US');
const fold=s=>String(s??'').normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
let curated=[],atlas=[],meta=null,visible=[],atlasResults=[],view='edition',page=1;
const rules=new Set(),pageSize=60;
const rooms={Cultivation:'What conditions let artistic work emerge and continue?',Devotion:'What does repeated attention make possible?',Being:'Which forms of life and consciousness can enter the frame?',Interrelation:'How does care change the meaning of a collection?'};
function showView(next){view=['edition','atlas','sources'].includes(next)?next:'edition';document.body.classList.toggle('inner-view',view!=='edition');$('#opening').hidden=view!=='edition';for(const n of ['edition','atlas','sources'])$('#'+n+'-view').hidden=n!==view;$$('[data-view]').forEach(a=>{a.classList.toggle('selected',a.dataset.view===view);if(a.dataset.view===view)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});$('#wander').textContent=view==='atlas'?'RANDOM RECORD ↗':'RANDOM EXHIBIT ↗';if(view==='atlas')renderAtlas();if(view==='sources')renderSources();}
window.addEventListener('hashchange',()=>{showView(location.hash.slice(1));if(['edition','atlas','sources'].includes(location.hash.slice(1)))window.scrollTo({top:0,behavior:'instant'});});showView(location.hash.slice(1)||'edition');
function render(){const q=fold($('#search').value.trim());const includeUnknown=$('#include-unknown').checked;visible=curated.filter(d=>(!q||fold([d.name,d.place,d.desc,d.question,d.room].join(' ')).includes(q))&&[...rules].every(r=>d[r]===true||(d[r]==null&&includeUnknown)));$$('.column').forEach(col=>{const entries=visible.filter(d=>d.room===col.dataset.room);col.querySelector('.cards').innerHTML=entries.length?entries.map(d=>`<button class="card" data-id="${esc(d.id)}" aria-label="Explore ${esc(d.name)}">${plate(d)}${d.kind!=='Institution'?`<span class="badge">${esc(d.kind.toUpperCase())}</span>`:''}<h3>${esc(d.name)}</h3><span class="meta">${esc(d.place)}</span><p class="desc">${esc(d.desc)}</p><p class="question">${esc(d.question)}</p><span class="bottom"><span>CASE ${esc(d.id.replace('curated-','').padStart(3,'0'))}</span><span>${d.url?'CURATED CASE':'PROPOSITION'}</span></span><span class="enter">Enter exhibit ↗</span></button>`).join(''):'<p class="empty-column">No cases in this room meet the selected conditions.</p>'});$('#count').textContent=`${visible.length} / ${curated.length} CASES WITHIN YOUR DEFINITION`;$('#empty').hidden=!!visible.length;$$('.card[data-id]').forEach(b=>b.onclick=()=>openExhibit(curated.find(d=>d.id===b.dataset.id)));}
function openDialog(content){$('#detail-content').innerHTML=content;if(!$('#detail').open)$('#detail').showModal();$('#detail').scrollTop=0;}
function openExhibit(d){if(!d)return;const cNames={objects:'Physical objects',building:'Dedicated museum building',public:'Public access'};openDialog(`<p class="eyebrow">CASE ${esc(d.id.replace('curated-','').padStart(3,'0'))} / ${esc(d.kind.toUpperCase())}</p><h2 id="detail-title">${esc(d.name)}</h2><span class="meta">${esc(d.place)}</span><p class="fine">${esc(d.status)}</p><div class="detail-plate">${plate(d)}</div><p>${esc(d.text)}</p><p class="provocation">${esc(d.question)}</p><div class="detail-context"><p class="eyebrow">EXTREME PRESENCE / ${esc(d.room.toUpperCase())}</p><p>${esc(d.context)}</p></div><div class="rules">${Object.entries(cNames).map(([k,v])=>`<span class="${d[k]==null?'unknown':''}">${d[k]===true?'● YES':d[k]===false?'○ NO':'? UNASSESSED'} / ${v}</span>`).join('')}</div><p class="fine">${esc(d.criteriaNote)} Classifications and thematic links are editorial, not an official museum definition.</p>${d.sources.length?'<p class="eyebrow">INSTITUTIONAL SOURCES / CHECKED 23 OCT 2026</p>'+d.sources.map((u,i)=>`<a class="source-link" href="${esc(safeUrl(u))}" target="_blank" rel="noopener">${i+1}. ${esc(new URL(u).hostname)} ↗</a>`).join(''):'<p class="fine">A hypothetical case. No specific institution is represented.</p>'}<p class="fine">Illustration: original interpretive study, not a photograph of this institution.</p>`);}
$$('[data-rule]').forEach(b=>b.onclick=()=>{rules.has(b.dataset.rule)?rules.delete(b.dataset.rule):rules.add(b.dataset.rule);b.setAttribute('aria-pressed',String(rules.has(b.dataset.rule)));b.textContent=b.textContent.replace(/[+−]$/,rules.has(b.dataset.rule)?'−':'+');render()});$('#reset').onclick=()=>{rules.clear();$$('[data-rule]').forEach(b=>{b.setAttribute('aria-pressed','false');b.textContent=b.textContent.replace('−','+')});$('#search').value='';$('#include-unknown').checked=false;render()};$('#search').oninput=render;$('#include-unknown').onchange=render;$('#definition-link').onclick=()=>{location.hash='definition';showView('edition');$('#definition').scrollIntoView({block:'start'});$('[data-rule]').focus({preventScroll:true})};$('#start-route').onclick=()=>openExhibit(curated.find(d=>d.name.startsWith('Hartwig')));
function category(type){const t=fold(type);if(!t)return 'Unclassified';if(/fine art|\bart\b|decorative|photograph|sculpture/.test(t))return 'Art';if(/science|natural|botan|zool|geolog|ecolog|aquari|planetari/.test(t))return 'Science & nature';if(/transport|rail|aviation|maritime|aircraft|automobil|motor|industry|industrial|technolog|computer|military aviation/.test(t))return 'Technology & transport';if(/history|historic|archaeolog|ethnolog|ethnograph|biograph|military|cultur|religio|herita|local|memor|war/.test(t))return 'History & society';return 'Other reported subject'}
function filterAtlas(){const q=fold($('#atlas-search').value.trim()),country=$('#country').value,subject=$('#subject').value;atlasResults=atlas.filter(d=>(!country||d.country===country)&&(!subject||d.group===subject)&&(!q||d.search.includes(q)));page=1;renderAtlas()}
function renderAtlas(){if(!atlas.length){$('#atlas-count').textContent='Loading the atlas…';return;}const pages=Math.max(1,Math.ceil(atlasResults.length/pageSize));page=Math.min(page,pages);const start=(page-1)*pageSize,items=atlasResults.slice(start,start+pageSize);$('#atlas-count').textContent=`${fmt(atlasResults.length)} OF ${fmt(atlas.length)} RECORDS`;$('#atlas-grid').innerHTML=items.length?items.map(d=>`<button class="atlas-card" data-atlas-id="${esc(d.id)}" aria-label="View record for ${esc(d.name)}"><span class="accession"><span>${esc(d.id.slice(-6).toUpperCase())}</span><span>↗</span></span><h2>${esc(d.name)}</h2><p>${esc([d.locality,d.country].filter(Boolean).join(' / '))}</p><span class="atlas-type"><span>${esc(d.group)}</span><span>${d.sources.length} SOURCE${d.sources.length>1?'S':''}</span></span></button>`).join(''):'<div class="view-empty">No records match these filters. Try a broader search or another country.</div>';$('#page-info').textContent=`PAGE ${page} / ${pages}`;$('#prev-page').disabled=page===1;$('#next-page').disabled=page>=pages;$('#atlas-random').disabled=!atlasResults.length;$$('[data-atlas-id]').forEach(b=>b.onclick=()=>openRecord(atlas.find(d=>d.id===b.dataset.atlasId)));}
function openRecord(d){if(!d)return;openDialog(`<p class="eyebrow">WORLD ATLAS / DIRECTORY IMPORT</p><h2 id="detail-title">${esc(d.name)}</h2><p>${esc(d.country)}</p><dl class="record-facts"><dt>Location in list</dt><dd>${esc(d.locality||'Not recorded')}</dd><dt>Reported type</dt><dd>${esc(d.type||'Not recorded')}</dd><dt>Browse category</dt><dd>${esc(d.group)}${d.type?' · grouped from reported type':''}</dd><dt>Source section</dt><dd>${esc(d.section||'Not recorded')}</dd><dt>Retrieved</dt><dd>${esc(meta?.retrieved||'2026-10-23')}</dd><dt>Current operation</dt><dd>Not individually verified</dd></dl><div class="record-question">This list calls it a museum.<br>What would you need to know to agree?</div><p class="fine">Physical collection, dedicated building, and public access are unassessed for this imported record. It is not included in the exhibition’s definition test.</p>${d.article?`<a class="source" href="${esc(safeUrl(d.article))}" target="_blank" rel="noopener">READ THE ENCYCLOPEDIA ENTRY ↗</a>`:''}<p class="eyebrow">FOUND IN ${d.sources.length} MUSEUM LIST${d.sources.length>1?'S':''}</p>${d.sources.map(u=>`<a class="source-link" href="${esc(safeUrl(u))}" target="_blank" rel="noopener">${esc(decodeURIComponent(u.split('/').pop()).replaceAll('_',' '))} ↗</a>`).join('')}<p class="fine">Attribution: Wikipedia contributors. List-derived data under <a href="https://creativecommons.org/licenses/by-sa/4.0/" target="_blank" rel="noopener">CC BY-SA 4.0</a>. Follow the source for its edit history, context, and corrections.</p>`)}
$('#atlas-search').oninput=filterAtlas;$('#country').onchange=filterAtlas;$('#subject').onchange=filterAtlas;$('#atlas-reset').onclick=()=>{$('#atlas-search').value='';$('#country').value='';$('#subject').value='';filterAtlas()};$('#prev-page').onclick=()=>{page--;renderAtlas();$('.atlas-controls').scrollIntoView({block:'start'})};$('#next-page').onclick=()=>{page++;renderAtlas();$('.atlas-controls').scrollIntoView({block:'start'})};$('#atlas-random').onclick=()=>{if(atlasResults.length)openRecord(atlasResults[Math.floor(Math.random()*atlasResults.length)])};$('#wander').onclick=()=>{if(view==='atlas')$('#atlas-random').click();else if(visible.length)openExhibit(visible[Math.floor(Math.random()*visible.length)]);else $('#empty').scrollIntoView()};
function renderSources(){if(!meta)return;$('#source-summary').textContent=`${fmt(meta.count)} deduplicated records from ${fmt(meta.contributingLists)} contributing lists, covering ${meta.countries} countries and territories. Retrieved ${meta.retrieved}. ${meta.listsAttempted} list pages were attempted; the full fetch log is below.`;const q=fold($('#source-search').value);const sources=meta.sources.filter(s=>!q||fold(s.title+' '+s.country).includes(q));$('#source-list').innerHTML=sources.map(s=>`<div class="source-row ${s.status!=='ok'?'failed':''}"><a href="${esc(safeUrl(s.url))}" target="_blank" rel="noopener">${esc(s.title)} ↗</a><span>${esc(s.country)}</span><span>${s.status==='ok'?`${fmt(s.records)} extracted rows`:esc(s.status.replaceAll('_',' '))}</span></div>`).join('')||'<p class="fine">No source titles match this search.</p>';$('#curated-sources').innerHTML=curated.filter(d=>d.sources.length).map(d=>`<div class="source-row"><span>${esc(d.name)}</span><span>${esc(d.room)}</span><span>${d.sources.map((u,i)=>`<a href="${esc(safeUrl(u))}" target="_blank" rel="noopener">Source ${i+1} ↗</a>`).join(' · ')}</span></div>`).join('');}$('#source-search').oninput=renderSources;
$('#about').onclick=()=>openDialog(`<p class="eyebrow">MUSEUM OF MUSEUMS / AISHWARYA KHANDUJA</p><h2 id="detail-title">A MUSEUM IS A TECHNOLOGY OF ATTENTION.</h2><p>It gives some things a place, a duration, and an audience. It teaches us what to notice. This museum treats those decisions as its collection.</p><p>The Extreme Presence edition follows five lines of inquiry: cultivation, devotion, memory, being, and interrelation. Each brings a different institutional possibility into view.</p><p class="provocation">What would a museum need to be, to make room for what does not yet exist?</p><p>Explore the selected cases, change the definition, or enter the world atlas. The atlas keeps the boundaries drawn by its source lists visible; it does not resolve them into one final definition.</p><p class="fine">A project by <a href="https://analoguegroup.org/" target="_blank" rel="noopener">Analogue Group</a> in collaboration with <a href="https://www.hartwigartfoundation.nl/en/programmes/extreme-presence/" target="_blank" rel="noopener">Extreme Presence</a>, <a href="https://www.hartwigproxy.nl/" target="_blank" rel="noopener">Hartwig Proxy</a> / <a href="https://www.hartwigartfoundation.nl/" target="_blank" rel="noopener">Hartwig Art Foundation</a>. Visual direction draws on the Extreme Presence programme page. The living-archive premise draws on Second Renaissance.</p>`);
$('#event-info').onclick=()=>openDialog(`<p class="eyebrow">HARTWIG ART FOUNDATION / AMSTERDAM</p><h2 id="detail-title" class="event-dialog-title">EXTREME PRESENCE<br>23—25 OCTOBER 2026</h2><p>The gathering brings art into conversation with technology, consciousness, devotion, and the ethics of interrelation. This project asks how museums themselves shape those encounters.</p><div class="event-session"><p class="eyebrow">SUNDAY 25 OCT / 14:00—15:30 / HARTWIG PROXY</p><h3>Technologies of Cultivation</h3><p>Aishwarya Khanduja joins Haley Albert, Xin Liu, and William Morgan, moderated by Leonardo Dellanoce and Arthur Steiner, to discuss the conditions that sustain artistic R&D.</p></div><p>Hartwig’s own developing museum is a starting case: an institution designed to host artists and new production. The exhibition’s five rooms are editorial responses to the gathering’s themes.</p><a class="source" href="https://www.hartwigartfoundation.nl/en/programmes/extreme-presence/" target="_blank" rel="noopener">VIEW THE OFFICIAL PROGRAMME ↗</a><p class="fine">Event details from Hartwig Art Foundation.</p>`);
$$('.close').forEach(b=>b.onclick=()=>b.closest('dialog').close());$$('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));$('#open-question').onclick=()=>{try{$('#thought').value=localStorage.getItem('mom-note')||''}catch{}$('#saved').textContent='';$('#notes').showModal()};$('#save-note').onclick=()=>{try{localStorage.setItem('mom-note',$('#thought').value);$('#saved').textContent='Kept in this browser.'}catch{$('#saved').textContent='This browser could not save your note. Copy it before closing.'}};
async function getJson(path){const r=await fetch(path);if(!r.ok)throw new Error(`Could not load ${path}`);return r.json()}
getJson('data/curated.json').then(d=>{curated=d;$('#edition-total').textContent=d.length;render();renderSources()}).catch(()=>{$('#count').textContent='The exhibition could not load. Please reload the page.'});
Promise.all([getJson('data/atlas.json'),getJson('data/sources.json')]).then(([rows,s])=>{meta=s;atlas=rows.map(d=>({...d,group:category(d.type),search:fold([d.name,d.locality,d.country,d.type].join(' '))}));atlasResults=atlas;$('#atlas-total').textContent=fmt(atlas.length);$('#atlas-stats').textContent=`${fmt(atlas.length)} records. ${fmt(s.contributingLists)} lists. ${s.countries} countries and territories.`;const counts=new Map();atlas.forEach(d=>counts.set(d.country,(counts.get(d.country)||0)+1));$('#country').innerHTML='<option value="">All countries / territories</option>'+[...counts].sort((a,b)=>a[0].localeCompare(b[0])).map(([c,n])=>`<option value="${esc(c)}">${esc(c)} (${fmt(n)})</option>`).join('');filterAtlas();renderSources()}).catch(()=>{$('#atlas-total').textContent='RETRY';$('#atlas-stats').textContent='The atlas could not load. Reload the page to try again.';$('#atlas-count').textContent='Atlas unavailable';$('#load-error').hidden=false;$('#load-error').textContent='Some collection data could not be loaded. Please reload the page. The curated exhibition may still be available.'});

function updateNavTone(){document.body.classList.toggle('over-hero',!$('#opening').hidden&&$('#opening').getBoundingClientRect().bottom>370)}window.addEventListener('scroll',updateNavTone,{passive:true});window.addEventListener('hashchange',updateNavTone);updateNavTone();
$('#contrast').onclick=()=>{const on=document.body.classList.toggle('high-contrast');$('#contrast').setAttribute('aria-pressed',String(on));};
